## 流式响应（Streaming Responses）

Fetch API 支持通过 `ReadableStream` 逐块读取响应数据，适用于大文件下载和实时数据处理。

```typescript
async function fetchWithProgress(
  url: string,
  onProgress: (loaded: number, total: number) => void,
): Promise<Uint8Array> {
  const response = await fetch(url);
  const contentLength = Number(response.headers.get('Content-Length') ?? 0);
  const reader = response.body!.getReader();

  const chunks: Uint8Array[] = [];
  let loaded = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    chunks.push(value);
    loaded += value.length;
    onProgress(loaded, contentLength);
  }

  const result = new Uint8Array(loaded);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.length;
  }

  return result;
}

async function streamText(url: string): Promise<void> {
  const response = await fetch(url);
  const reader = response.body!.pipeThrough(new TextDecoderStream()).getReader();

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    console.log('Chunk:', value);
  }
}
```

```mermaid
flowchart LR
    Response["Response"] --> Body["ReadableStream"]
    Body --> Reader["getReader()"]
    Reader --> Read1["read() → chunk 1"]
    Read1 --> Read2["read() → chunk 2"]
    Read2 --> Read3["read() → chunk N"]
    Read3 --> Done["done: true"]
```

